const API=window.__HATCHABLE__?.api||"/api",$=s=>document.querySelector(s);
const S={view:"explorer",patients:[],selected:null,sources:[],overview:null,member:null,headers:[],rows:[],file:null,selectedSource:null,externalMode:true,hospitals:[]};
const esc=v=>String(v??"").replace(/[&<>"']/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]});
const titles={home:"Command Center",patients:"Patients",population:"Population",network:"PHC Network",resources:"Resources",actions:"Actions",reports:"Reports",explorer:"Hospital & Data Explorer",data:"Data & Trust"};
function toast(a,b){var x=document.createElement("div");x.className="toast";x.innerHTML="<b>"+esc(a)+"</b>"+(b?"<small>"+esc(b)+"</small>":"");document.body.appendChild(x);setTimeout(function(){x.remove()},3000)}
async function api(p,o){var r=await fetch(API+p,Object.assign({cache:"no-store"},o||{}, {headers:Object.assign({"Content-Type":"application/json"},(o&&o.headers)||{})}));var d={};try{d=await r.json()}catch(e){}if(!r.ok)throw Error(d.error||"Request failed");return d}
function section(h,p){return "<div class='section-title'><div><p class='eyebrow'>CARE & CTRL</p><h1>"+h+"</h1><p>"+p+"</p></div></div>"}
function help(a,b){return "<div class='helper'><b>What this does:</b> "+a+"<br><b>What you'll get:</b> "+b+"</div>"}
function metric(a,b,c){return "<article class='metric'><div class='label'>"+a+" <span>•</span></div><span class='value'>"+esc(b)+"</span><small>"+c+"</small></article>"}
function home(){if(S.externalMode){var c=liveCounts();return "<div class=\"hero\"><div><p class=\"eyebrow\">COMMAND CENTER · LIVE SOURCE</p><h1>See earlier.<br><em>Decide smarter.</em></h1><p class=\"hero-copy\">Your selected healthcare dataset is now the source of truth. Watch the live clinical picture change without mixing in unrelated records.</p></div><div class=\"hero-state\"><div class=\"state-orb\"><i></i></div><div><small>ACTIVE DATA SOURCE</small><b>LIVE FHIR</b><span>"+esc(S.selectedSource?.freshness||"Live connection")+"</span></div></div></div>"+liveSourceBadge()+"<div class=\"metrics\">"+metric("Patients",c.patients,"Current source records")+metric("Observations",c.signals,"Clinical measurements")+metric("Conditions",c.conditions,"Clinical context")+metric("Encounters",c.encounters,"Healthcare interactions")+"</div><div class=\"dashboard-grid\"><article class=\"panel signal-dashboard\"><div class=\"panel-head\"><div><p class=\"eyebrow\">LIVE SIGNAL PULSE</p><h2>Clinical activity at a glance</h2><p class=\"panel-copy\">A visual pulse of how much observation data is attached to each returned patient.</p></div><span class=\"badge\">LIVE</span></div><div class=\"pulse-bars\">"+S.patients.slice(0,12).map(function(p,i){var n=Number(p.signal_count||0),h=Math.max(10,Math.min(100,10+n*3));return "<div class=\"pulse-col\"><span style=\"height:"+h+"%\"></span><small>"+String(i+1).padStart(2,"0")+"</small></div>"}).join("")+"</div><div class=\"dashboard-legend\"><span><i></i> Observation volume</span><span>Source: "+esc(S.selectedSource?.endpoint||"FHIR")+"</span></div></article><article class=\"panel\"><div class=\"panel-head\"><div><p class=\"eyebrow\">SOURCE HEALTH</p><h2>Connection status</h2></div><span class=\"source-badge live\">CONNECTED</span></div><div class=\"health-stack\"><div><span>Patient records</span><b>"+c.patients+"</b></div><div><span>Clinical observations</span><b>"+c.signals+"</b></div><div><span>Last refresh</span><b>"+esc(S.selectedSource?.freshness||"—")+"</b></div></div><button class=\"button\" data-view=\"data\">Inspect provenance</button></article></div><div class=\"panel\"><div class=\"panel-head\"><div><p class=\"eyebrow\">CONNECTED LOOP</p><h2>From source → insight → action</h2><p class=\"panel-copy\">Operational action remains gated until the corresponding operational source is connected.</p></div><span class=\"badge\">HUMAN IN CONTROL</span></div><div class=\"journey\"><button class=\"journey-step\" data-view=\"patients\"><div class=\"journey-dot\">01</div><b>Patient</b><span>What changed?</span></button><button class=\"journey-step\" data-view=\"population\"><div class=\"journey-dot\">02</div><b>Population</b><span>What is changing?</span></button><button class=\"journey-step\" data-view=\"network\"><div class=\"journey-dot\">03</div><b>Operations</b><span>What data is missing?</span></button><button class=\"journey-step\" data-view=\"actions\"><div class=\"journey-dot\">04</div><b>Action</b><span>What can we safely do?</span></button></div></div></div><article class='panel copilot'><div class='panel-head'><div><p class='eyebrow'>CARE & CTRL COPILOT</p><h2>Ask the connected data</h2><p class='panel-copy'>Gemini answers only from the active source and clearly states when evidence is missing.</p></div><span class='badge'>GROUNDED AI</span></div><div class='prompt-row'><button class='prompt' data-p='attention'>What needs attention?</button><button class='prompt' data-p='pressure'>What patterns are visible?</button><button class='prompt' data-p='action'>Summarise the connected dataset</button></div><div id='copilotAnswer' class='empty dark-empty'><div class='empty-icon'>AI</div><h2>Copilot ready</h2><p>Choose a question to analyse the active source.</p></div></article></div>"}+[["01","Patient","What changed?","patients"],["02","Population","What is changing?","population"],["03","PHC pressure","Where is it building?","network"],["04","Resources","What will be needed?","resources"],["05","Action","What can we do?","actions"]];return "<div class='hero'><div><p class='eyebrow'>COMMAND CENTER · "+new Date().toLocaleDateString("en-IN")+"</p><h1>See earlier.<br><em>Decide smarter.</em></h1><p class='hero-copy'>CARE & CTRL connects changing patient signals to population patterns, facility pressure, resource needs and human-approved action — in one traceable workspace.</p></div><div class='hero-state'><div class='state-orb'><i></i></div><div><small>WORKSPACE STATE</small><b>"+(o.connected_sources?"Verified data connected":"Ready for your data")+"</b><span>Nothing is called live without a verified source.</span></div></div></div><div class='metrics'>"+metric("Patients needing attention",o.patients_needing_attention??"—","Verified signals")+metric("Active patients",o.active_patients??"—","Workspace records")+metric("Connected sources",o.connected_sources??"—","Verified connections")+metric("Human decisions pending",o.pending_human_decisions??"—","Awaiting review")+"</div><div class='workspace'><div><article class='panel'><div class='panel-head'><div><p class='eyebrow'>THE CONNECTED LOOP</p><h2>One story, from signal to action</h2><p class='panel-copy'>Every stage answers the next question. Click any stage.</p></div><span class='badge'>HUMAN IN CONTROL</span></div><div class='journey'>"+steps.map(function(s){return "<button class='journey-step' data-view='"+s[3]+"'><div class='journey-dot'>"+s[0]+"</div><b>"+s[1]+"</b><span>"+s[2]+"</span></button>"}).join("")+"</div></article><article class='panel'><div class='panel-head'><div><p class='eyebrow'>TRUST LAYER</p><h2>Evidence travels with every decision</h2></div><button class='button' data-view='data'>Review trust</button></div><div class='trust-row'><div class='trust-item'><b>Source</b><span>Where it came from.</span></div><div class='trust-item'><b>Freshness</b><span>When it was verified.</span></div><div class='trust-item'><b>Model</b><span>What produced the prediction.</span></div><div class='trust-item'><b>Approval</b><span>A person stays responsible.</span></div></div></article></div><article class='panel evidence-sentinel'><div class='panel-head'><div><p class='eyebrow'>EVIDENCE SENTINEL</p><h2>Know what the system actually knows</h2><p class='panel-copy'>A live integrity layer that separates connected evidence from unavailable or authorisation-gated data.</p></div><span class='badge'>TRACEABLE</span></div><div class='evidence-grid'><div><span>Source</span><b>"+esc(S.selectedSource?.type||"UNKNOWN")+"</b></div><div><span>Freshness</span><b>"+esc(S.selectedSource?.freshness||"Not available")+"</b></div><div><span>Clinical resources</span><b>"+Object.keys(S.selectedSource?.resource_counts||{}).length+"</b></div><div><span>Unavailable</span><b>"+(S.selectedSource?.unavailable_resources?.length||0)+"</b></div></div></article><article class='panel copilot'><div class='panel-head'><div><p class='eyebrow'>CARE & CTRL COPILOT</p><h2>Ask from the data you can trust</h2><p class='panel-copy'>Grounded in application state, not invented values.</p></div><span class='badge'>AI</span></div><div class='prompt-row'><button class='prompt' data-p='attention'>What needs attention?</button><button class='prompt' data-p='pressure'>Where is pressure building?</button><button class='prompt' data-p='action'>Explain the latest action</button><button class='prompt' id='edgeCopilot'>◉ Run on Snapdragon Edge</button></div><div id='copilotAnswer' class='empty dark-empty'><div class='empty-icon'>AI</div><h2>Ready to answer from your workspace</h2><p>Ask a question to see grounded context.</p></div></article></div>"}
function patientRows(a){if(!a.length)return "<div class='empty'><div class='empty-icon'>◉</div><h2>No patients yet</h2><p>Register a patient or use Hospital & Data Explorer → Upload CSV.</p></div>";return a.map(function(p){return "<button class='patient-row' data-patient='"+p.id+"'><div><b>"+esc(p.display_name)+"</b><small>"+esc(p.external_ref)+" · "+esc(p.sex||"Not specified")+"</small></div><div class='patient-meta'><b>"+esc(p.signal_count||0)+" signals</b><small>"+esc(p.last_signal_at?new Date(p.last_signal_at).toLocaleString("en-IN"):"No signal yet")+"</small></div></button>"}).join("")}
async function patientDetail(id){if(S.externalMode){var p=S.patients.find(function(x){return String(x.id)===String(id)});if(!p)return "<p>Patient not found.</p>";return "<p class='eyebrow'>CONNECTED PATIENT RECORD</p><h2>"+esc(p.display_name)+"</h2><div class='detail-sub'>"+esc(p.external_ref)+" · "+esc(p.sex||"Not specified")+" · "+esc(p.date_of_birth||"DOB unavailable")+"</div><div class='helper' style='margin-top:14px'><b>Source:</b> "+esc(p.source||S.selectedSource?.name||"Connected source")+"<br><b>Data state:</b> "+esc(p.dataType||"Source-provided")+"</div><div class='toolbar'><button class='button' data-view='explorer'>Change source</button></div>";}var d=await api("/patients/"+id),s=d.signals||[];return "<p class='eyebrow'>PATIENT DIGITAL TWIN</p><h2>"+esc(d.patient.display_name)+"</h2><div class='detail-sub'>"+esc(d.patient.external_ref)+" · "+esc(d.patient.status)+"</div><div class='toolbar'><button class='button primary' data-signal='"+id+"'>+ Add signal</button></div>"+(s.length?s.slice(0,15).map(function(x){return "<div class='signal'><span>"+esc(x.signal_type)+" "+esc(x.unit||"")+"</span><b>"+esc(x.value_numeric)+" <small>"+new Date(x.observed_at).toLocaleString("en-IN")+"</small></b></div>"}).join(""):"<p class='detail-sub'>No signals yet. Add one to start the timeline.</p>")}
async function patients(){if(!S.externalMode){var d=await api("/patients/list");S.patients=d.rows||[]}return section("Patients","Start with the individual signal, then follow its trajectory into the wider system.")+help("Register patients and inspect verified signals attached to their Digital Twin.","A searchable list and focused patient timeline.")+"<div class='toolbar'><input class='input' id='patientSearch' placeholder='Search patient or reference…'>"+(S.externalMode?"<span class='source-badge sim'>SOURCE-DRIVEN PATIENTS</span>":"<button class='button primary' id='addPatient'>+ Register patient</button>")+"</div><div class='patient-grid'><div class='patient-list' id='patientList'>"+patientRows(S.patients)+"</div><div class='detail' id='patientDetail'>"+(S.selected?await patientDetail(S.selected):"<div class='empty'><div class='empty-icon'>◉</div><h2>Select a patient</h2><p>Choose a patient to inspect its timeline.</p></div>")+"</div></div>"}
function population(){var n=S.patients.length,s=S.patients.reduce(function(a,p){return a+Number(p.signal_count||0)},0);return section("Population Intelligence","Move from individual changes to local patterns without losing source and freshness.")+help("Aggregates records currently available in your workspace.","Cohort size, signal volume and explicit evidence state.")+"<div class='cards'><div class='info-card'><p class='eyebrow'>COHORT</p><h3>Patients</h3><div class='big-number'>"+n+"</div><p>Current records.</p></div><div class='info-card'><p class='eyebrow'>SIGNALS</p><h3>Recorded signals</h3><div class='big-number'>"+s+"</div><p>Timestamped patient signals.</p></div><div class='info-card'><p class='eyebrow'>EVIDENCE</p><h3>State</h3><div class='big-number' style='font-size:20px'>Source-bound</div><p>No trend is invented without enough evidence.</p></div></div>"}
async function network(){var d=await api("/phc/network"),r=d.facilities||[];return section("PHC Network","See where facility pressure is building across connected facilities.")+help("Maps connected facilities and operational coverage.","Facility status, capacity and resource-record coverage.")+"<div class='table-wrap'><table><thead><tr><th>Facility</th><th>District</th><th>State</th><th>Status</th><th>Capacity</th><th>Records</th></tr></thead><tbody>"+(r.length?r.map(function(x){return "<tr><td><b>"+esc(x.name)+"</b></td><td>"+esc(x.district||"—")+"</td><td>"+esc(x.state||"—")+"</td><td>"+esc(x.status)+"</td><td>"+esc(x.capacity_total??"—")+"</td><td>"+esc(x.resource_records||0)+"</td></tr>"}).join(""):"<tr><td colspan='6'>No verified facilities connected yet.</td></tr>")+"</tbody></table></div>"}
async function resources(){var d=await api("/resources/forecast"),r=d.rows||[];return section("Resource Forecast","Translate operational pressure into a forward resource requirement.")+help("Calculates days-to-reorder from observed stock, usage and thresholds.","Transparent resource outlook; no forecast where underlying data is missing.")+"<div class='table-wrap'><table><thead><tr><th>Resource</th><th>Facility</th><th>Available</th><th>Daily use</th><th>Reorder</th><th>Days</th></tr></thead><tbody>"+(r.length?r.map(function(x){return "<tr><td><b>"+esc(x.resource_name)+"</b></td><td>"+esc(x.facility_name)+"</td><td>"+esc(x.quantity_available)+" "+esc(x.unit)+"</td><td>"+esc(x.average_daily_use)+"</td><td>"+esc(x.reorder_level)+"</td><td>"+(x.days_to_reorder==null?"Insufficient data":Number(x.days_to_reorder).toFixed(1)+" days")+"</td></tr>"}).join(""):"<tr><td colspan='6'>No resource inventory connected yet.</td></tr>")+"</tbody></table></div>"}
async function actions(){var d=await api("/actions/list"),r=d.rows||[];return section("Action Center","Review evidence, simulate consequences, and keep a human responsible for the final decision.")+help("Holds recommendations until a responsible person reviews the rationale and expected impact.","Pending actions, explicit approval controls and an audit trail.")+"<div class='toolbar'><button class='button dark' id='simulatorBtn'>Open what-if simulator</button></div><div class='cards'>"+(r.length?r.map(function(x){return "<article class='info-card'><span class='status'>"+esc(x.status)+"</span><h3>"+esc(x.action_type)+"</h3><p><b>Why:</b> "+esc(x.rationale)+"</p><p><b>Expected:</b> "+esc(x.expected_impact||"Not specified")+"</p>"+(x.status==="pending"?"<div class='modal-actions'><button class='button' data-action='"+x.id+"' data-status='rejected'>Reject</button><button class='button primary' data-action='"+x.id+"' data-status='approved'>Approve</button></div>":"")+"</article>"}).join(""):"<article class='info-card'><h3>No pending recommendations</h3><p>Verified recommendations will appear here for human review.</p></article>")+"</div>"}
function facilityConnection(endpoint){if(!S.selectedSource||!S.selectedSource.facility)return '';var h=S.selectedSource.facility;var live=endpoint?.liveEndpoint;var liveBlock=live?"<div class='connection-option'><span class='badge'>PUBLIC FHIR DISCOVERY</span><h3>Live patient endpoint found</h3><p>CARE & CTRL found a FHIR endpoint associated with this facility. It will test the endpoint and use its Patient + available clinical resources as the workspace source of truth if access is permitted.</p><button class='button primary' data-live-endpoint='"+esc(live.endpoint)+"'>Load live patient data</button><a class='button' target='_blank' rel='noopener' href='"+esc(live.endpoint)+"'>Open FHIR endpoint ↗</a></div>":"<div class='connection-option'><span class='badge'>PUBLIC FHIR DISCOVERY</span><h3>No public endpoint found</h3><p>No matching public patient endpoint was discovered in the checked directories. The hospital may still have a private or authorised API.</p><span class='source-badge'>DIRECTORY CHECKED</span></div>";return "<article class='explore-card facility-connection' id='facilityConnection'><p class='eyebrow'>SELECTED FACILITY · DATA CONNECTION</p><h2>"+esc(h.name)+"</h2><p>We found the facility in the public directory. The directory does <b>not</b> expose its private patient database. Choose an authorised patient feed or import an authorised hospital export to continue.</p><div class='connection-grid'>"+liveBlock+"<div class='connection-option'><span class='badge'>FACILITY</span><h3>Facility context</h3><p>Location, identity and public directory information are connected now.</p><button class='button' disabled>Connected</button></div><div class='connection-option'><span class='badge'>PATIENT DATA</span><h3>Fallback: synthetic test feed</h3><p>Use this only when an authorised hospital source is unavailable. These records are synthetic/test data and are <b>not</b> patients of the selected hospital.</p><button class='button' data-connect-source='hapi-r4'>Use synthetic demo</button></div><div class='connection-option'><span class='badge'>YOUR DATA</span><h3>Authorised hospital CSV</h3><p>Upload an approved export from this facility and CARE & CTRL will validate, map and import it.</p><button class='button' data-scroll-csv>Upload CSV</button></div><div class='connection-option'><span class='badge'>AUTHORISED FHIR</span><h3>Connect an endpoint</h3><p>If this hospital uses a protected FHIR server, paste its authorised R4 base URL and CARE & CTRL will test it before loading any patient data.</p><input class='input' id='manualFhirEndpoint' placeholder='https://hospital.example/fhir/R4' style='width:100%;margin:8px 0'><button class='button primary' id='manualFhirBtn'>Test & connect</button></div></div></article>"}
async function explorer(){var d=await api("/explorer/sources");S.sources=d.sources||[];var endpoint=S.selectedSource?.endpointDiscovery||null;if(S.selectedSource?.facility&&!endpoint&&!S.selectedSource?.endpointDiscoveryChecked){S.selectedSource.endpointDiscoveryChecked=true;try{endpoint=await api("/explorer/endpoint-match?name="+encodeURIComponent(S.selectedSource.facility.name)+"&city="+encodeURIComponent(S.selectedSource.facility.city||"")+"&country="+encodeURIComponent(S.selectedSource.facility.country||""));S.selectedSource.endpointDiscovery=endpoint}catch(e){endpoint={liveEndpoint:null,note:"Endpoint discovery temporarily unavailable."};S.selectedSource.endpointDiscovery=endpoint}}return section("Hospital & Data Explorer","Choose exactly one source of truth for this CARE & CTRL workspace.")+"<div class=\"source-choice\"><article class=\"choice-card\"><div class=\"choice-kicker\"><span class=\"choice-icon\">⌁</span><span class=\"source-badge live\">OPTION 01 · LIVE</span></div><h3>Connect a live healthcare source</h3><p>Find a hospital worldwide, discover an accessible FHIR endpoint, and let its current Patient + clinical resources drive the workspace.</p><button class=\"button primary\" data-scroll-hospitals>Find a hospital</button></article><article class=\"choice-card\"><div class=\"choice-kicker\"><span class=\"choice-icon\">↥</span><span class=\"source-badge\">OPTION 02 · IMPORT</span></div><h3>Upload a healthcare database</h3><p>Import an authorised CSV, map the columns, validate it, and make the imported snapshot the workspace source of truth.</p><button class=\"button\" data-scroll-csv>Upload healthcare CSV</button></article></div>"+liveSourceBadge()+facilityConnection(endpoint)+help("Start with either a live connected source or an authorised healthcare database upload. The active source controls the downstream patient and population views.","A visible source state, freshness, provenance and a traceable path from data to decision.")+"<article class='source-hub'><div class='hub-top'><div><p class='eyebrow'>START HERE · FACILITY DISCOVERY</p><h2>Where should CARE & CTRL look?</h2><p>Search worldwide by city, state, country or hospital name. Or use your location to find nearby facilities.</p></div><button class='button primary' id='nearMe'>◎ Hospitals near me</button></div><div class='location-search'><input class='input' id='locationQuery' placeholder='Try: Chennai, Madurai, Tamil Nadu, London, New York…'><button class='button dark' id='findHospitals'>Find hospitals</button></div><div id='hospitalResults' class='hospital-results'><div class='empty compact'><div class='empty-icon'>⌖</div><h2>Search a location to begin</h2><p>Hospital listings come from OpenStreetMap. They are facility data, not private patient records.</p></div></div></article><div id='facilityConnection'></div><div class='explorer explorer-lower'><article class='explore-card'><p class='eyebrow'>PATIENT-DATA SOURCES</p><h2>Use a connected data source</h2><p>These are the sources that can actually provide patient records to the workspace. Synthetic/test data is clearly labelled.</p><div class='source-list' id='sourceList'>"+sourceRows(S.sources)+"</div></article><article class='explore-card'><p class='eyebrow'>YOUR ORGANISATION</p><h2>Upload healthcare CSV</h2><p>For a hospital that has structured data but no integration yet: upload → preview → map → validate → import.</p><div class='dropzone'><input id='csvFile' type='file' accept='.csv,text/csv'><label for='csvFile'>Choose CSV file<br><span>Nothing imports until you confirm.</span></label></div><div id='csvStatus'></div></article></div>"}
function sourceRows(r){return r.map(function(s){return "<div class='source-row'><div><b>"+esc(s.name)+"</b><small>"+esc(s.region)+" · "+esc(s.freshness)+"</small></div><div class='source-actions'><span class='source-badge'>"+esc(s.type)+"</span><button class='button' data-source='"+s.id+"'>View</button></div></div>"}).join("")}
async function reports(){var d=await api("/reports/summary"),r=d.events||[];return section("Reports","Trace what the system saw, recommended and what people decided.")+help("Turns system events into a traceable decision record.","Recent audit events, action states and source provenance.")+"<div class='cards'><div class='info-card'><h3>Audit events</h3><div class='big-number'>"+r.length+"</div></div><div class='info-card'><h3>Actions</h3><div class='big-number'>"+(d.actions||[]).reduce(function(a,x){return a+Number(x.count||0)},0)+"</div></div><div class='info-card'><h3>Sources</h3><div class='big-number'>"+(d.sources||[]).length+"</div></div></div><div class='table-wrap'><table><thead><tr><th>Event</th><th>Detail</th><th>Actor</th><th>Time</th></tr></thead><tbody>"+(r.length?r.slice(0,30).map(function(e){return "<tr><td><b>"+esc(e.event_type)+"</b></td><td>"+esc(e.detail||"—")+"</td><td>"+esc(e.actor_id||"—")+"</td><td>"+new Date(e.created_at).toLocaleString("en-IN")+"</td></tr>"}).join(""):"<tr><td colspan='4'>No audit events yet.</td></tr>")+"</tbody></table></div>"}
function dataView(){var o=S.overview||{};return section("Data & Trust","Know what is connected, what is fresh, what was imported, and what the system is allowed to claim.")+help("Makes provenance, freshness, authentication and human-control visible.","A trust layer distinguishing live, imported, research and simulated sources.")+"<div class='cards'><div class='info-card'><p class='eyebrow'>IDENTITY</p><h3>Workspace</h3><div class='big-number' style='font-size:20px'>"+esc(S.member?.display_name||"Authenticated")+"</div><p>"+esc(S.member?.role||"Workspace user")+"</p></div><div class='info-card'><p class='eyebrow'>SOURCES</p><h3>Connected</h3><div class='big-number'>"+esc(o.connected_sources??0)+"</div><p>Verified connected sources.</p></div><div class='info-card'><p class='eyebrow'>SAFETY</p><h3>Human approval</h3><div class='big-number' style='font-size:20px'>Required</div><p>Recommendations do not auto-approve.</p></div></div>"}
function liveSourceBadge(){if(!S.selectedSource)return "";var s=S.selectedSource;var live=s.type==="LIVE FHIR";return "<div class='active-source'><span class='source-pulse "+(live?"live":"")+"' ></span><div><b>"+esc(live?"LIVE FHIR":"IMPORTED SNAPSHOT")+"</b><small>"+esc(s.name||s.endpoint||"Active healthcare dataset")+" · "+esc(s.freshness||"Source selected")+"</small></div><button class='button' data-view='explorer'>Change source</button></div>"}
function sourceBoundPage(title,desc,body){return section(title,desc)+liveSourceBadge()+body}
function liveCounts(){var p=S.patients||[],signals=p.reduce(function(a,x){return a+Number(x.signal_count||0)},0),conds=p.reduce(function(a,x){return a+(x.conditions||[]).length},0),enc=p.reduce(function(a,x){return a+(x.encounters||[]).length},0);return {patients:p.length,signals:signals,conditions:conds,encounters:enc}}
patientDetail=async function(id){if(!S.externalMode)return await patientDetailDb(id);var p=S.patients.find(function(x){return String(x.id)===String(id)});if(!p)return "<p>Patient not found.</p>";var sig=p.signals||p.latest_signals||[],conds=p.conditions||[],enc=p.encounters||[];return "<p class='eyebrow'>CONNECTED PATIENT DIGITAL TWIN</p><h2>"+esc(p.display_name)+"</h2><div class='detail-sub'>"+esc(p.external_ref)+" · "+esc(p.sex||"Not specified")+" · "+esc(p.date_of_birth||"DOB unavailable")+"</div><div class='helper' style='margin-top:14px'><b>Source:</b> "+esc(p.source||S.selectedSource?.name||"Connected source")+"<br><b>Data state:</b> "+esc(p.dataType||"Source-provided")+"<br><b>Freshness:</b> "+esc(S.selectedSource?.freshness||"Live source")+"</div><div class='twin-grid'><div><p class='eyebrow'>OBSERVATIONS · "+sig.length+"</p>"+(sig.length?sig.slice(0,15).map(function(x){return "<div class='signal'><span>"+esc(x.type||x.signal_type||"Observation")+" "+esc(x.unit||"")+"</span><b>"+esc(x.value??x.value_numeric??"—")+" <small>"+(x.observed_at?new Date(x.observed_at).toLocaleString("en-IN"):"Time unavailable")+"</small></b></div>"}).join(""):"<p class='detail-sub'>No observations were returned by this source.</p>")+"</div><div><p class='eyebrow'>CONDITIONS · "+conds.length+"</p>"+(conds.length?conds.slice(0,8).map(function(x){return "<div class='data-line'><span>"+esc(x.name)+"</span><b>"+esc(x.clinical_status||"Recorded")+"</b></div>"}).join(""):"<p class='detail-sub'>No Condition resources returned.</p>")+"<p class='eyebrow' style='margin-top:18px'>ENCOUNTERS · "+enc.length+"</p>"+(enc.length?enc.slice(0,6).map(function(x){return "<div class='data-line'><span>"+esc(x.type||"Encounter")+"</span><b>"+esc(x.status||"Recorded")+"</b></div>"}).join(""):"<p class='detail-sub'>No Encounter resources returned.</p>")+"</div></div><div class='toolbar'><button class='button' data-view='explorer'>Change source</button></div>"}
async function patientDetailDb(id){var d=await api("/patients/"+id),s=d.signals||[];return "<p class='eyebrow'>PATIENT DIGITAL TWIN</p><h2>"+esc(d.patient.display_name)+"</h2><div class='detail-sub'>"+esc(d.patient.external_ref)+" · "+esc(d.patient.status)+"</div><div class='toolbar'><button class='button primary' data-signal='"+id+"'>+ Add signal</button></div>"+(s.length?s.slice(0,15).map(function(x){return "<div class='signal'><span>"+esc(x.signal_type)+" "+esc(x.unit||"")+"</span><b>"+esc(x.value_numeric)+" <small>"+new Date(x.observed_at).toLocaleString("en-IN")+"</small></b></div>"}).join(""):"<p class='detail-sub'>No signals yet. Add one to start the timeline.</p>")}
population=function(){var c=liveCounts();return sourceBoundPage("Population Intelligence","See the population pattern emerging from the currently active healthcare source.","<div class='cards'><div class='info-card'><p class='eyebrow'>COHORT</p><h3>Patients</h3><div class='big-number'>"+c.patients+"</div><p>Records returned by the active source.</p></div><div class='info-card'><p class='eyebrow'>OBSERVATIONS</p><h3>Clinical signals</h3><div class='big-number'>"+c.signals+"</div><p>FHIR Observation resources joined to patients.</p></div><div class='info-card'><p class='eyebrow'>CLINICAL CONTEXT</p><h3>Conditions + encounters</h3><div class='big-number'>"+(c.conditions+c.encounters)+"</div><p>"+c.conditions+" conditions · "+c.encounters+" encounters.</p></div></div><div class='panel live-feed'><div class='panel-head'><div><p class='eyebrow'>SOURCE TRACE</p><h2>Population follows the selected dataset</h2><p class='panel-copy'>No unrelated workspace records are mixed into this view.</p></div><span class='badge'>SOURCE-BOUND</span></div><div class='feed-line'><span>Endpoint</span><b>"+esc(S.selectedSource?.endpoint||S.selectedSource?.name||"Imported workspace")+"</b></div><div class='feed-line'><span>Last fetch</span><b>"+esc(S.selectedSource?.freshness||"Imported snapshot")+"</b></div></div>")}
network=async function(){if(S.externalMode)return sourceBoundPage("PHC Network","Facility operations require an operational source; the selected patient FHIR endpoint does not expose inventory or PHC capacity here.","<div class='empty'><div class='empty-icon'>⌁</div><h2>Operational source not connected</h2><p>The selected live FHIR source provides patient/clinical resources. CARE & CTRL will not invent PHC capacity or resource records from them.</p><button class='button primary' data-view='explorer'>Connect an operations source</button></div>");return await networkDb()}
async function networkDb(){var d=await api("/phc/network"),r=d.facilities||[];return section("PHC Network","See where facility pressure is building across connected facilities.")+help("Maps connected facilities and operational coverage.","Facility status, capacity and resource-record coverage.")+"<div class='table-wrap'><table><thead><tr><th>Facility</th><th>District</th><th>State</th><th>Status</th><th>Capacity</th><th>Records</th></tr></thead><tbody>"+(r.length?r.map(function(x){return "<tr><td><b>"+esc(x.name)+"</b></td><td>"+esc(x.district||"—")+"</td><td>"+esc(x.state||"—")+"</td><td>"+esc(x.status)+"</td><td>"+esc(x.capacity_total??"—")+"</td><td>"+esc(x.resource_records||0)+"</td></tr>"}).join(""):"<tr><td colspan='6'>No verified facilities connected yet.</td></tr>")+"</tbody></table></div>"}
resources=async function(){if(S.externalMode)return sourceBoundPage("Resource Forecast","Resource forecasting needs an operational inventory source; it is never inferred from patient records.","<div class='empty'><div class='empty-icon'>◌</div><h2>Inventory source not connected</h2><p>No stock, consumption or reorder records were returned by the selected patient-data endpoint.</p><button class='button primary' data-view='explorer'>Connect operations data</button></div>");return await resourcesDb()}
async function resourcesDb(){var d=await api("/resources/forecast"),r=d.rows||[];return section("Resource Forecast","Translate operational pressure into a forward resource requirement.")+help("Calculates days-to-reorder from observed stock, usage and thresholds.","Transparent resource outlook; no forecast where underlying data is missing.")+"<div class='table-wrap'><table><thead><tr><th>Resource</th><th>Facility</th><th>Available</th><th>Daily use</th><th>Reorder</th><th>Days</th></tr></thead><tbody>"+(r.length?r.map(function(x){return "<tr><td><b>"+esc(x.resource_name)+"</b></td><td>"+esc(x.facility_name)+"</td><td>"+esc(x.quantity_available)+" "+esc(x.unit)+"</td><td>"+esc(x.average_daily_use)+"</td><td>"+esc(x.reorder_level)+"</td><td>"+(x.days_to_reorder==null?"Insufficient data":Number(x.days_to_reorder).toFixed(1)+" days")+"</td></tr>"}).join(""):"<tr><td colspan='6'>No resource inventory connected yet.</td></tr>")+"</tbody></table></div>"}
actions=async function(){if(S.externalMode)return sourceBoundPage("Action Center","Live clinical data can inform evidence, but CARE & CTRL will not create operational actions without a connected operational source.","<div class='empty'><div class='empty-icon'>✓</div><h2>Human action layer is waiting for operational evidence</h2><p>The selected source contains patient clinical data. No unrelated action queue is shown as if it came from this hospital.</p><button class='button primary' data-view='explorer'>Connect operations data</button></div>");return await actionsDb()}
async function actionsDb(){var d=await api("/actions/list"),r=d.rows||[];return section("Action Center","Review evidence, simulate consequences, and keep a human responsible for the final decision.")+help("Holds recommendations until a responsible person reviews the rationale and expected impact.","Pending actions, explicit approval controls and an audit trail.")+"<div class='toolbar'><button class='button dark' id='simulatorBtn'>Open what-if simulator</button></div><div class='cards'>"+(r.length?r.map(function(x){return "<article class='info-card'><span class='status'>"+esc(x.status)+"</span><h3>"+esc(x.action_type)+"</h3><p><b>Why:</b> "+esc(x.rationale)+"</p><p><b>Expected:</b> "+esc(x.expected_impact||"Not specified")+"</p>"+(x.status==="pending"?"<div class='modal-actions'><button class='button' data-action='"+x.id+"' data-status='rejected'>Reject</button><button class='button primary' data-action='"+x.id+"' data-status='approved'>Approve</button></div>":"")+"</article>"}).join(""):"<article class='info-card'><h3>No pending recommendations</h3><p>Verified recommendations will appear here for human review.</p></article>")+"</div>"}
reports=async function(){if(S.externalMode){var c=liveCounts();return sourceBoundPage("Reports","Trace the evidence returned by the active source without mixing in unrelated workspace events.","<div class='cards'><div class='info-card'><h3>Patients</h3><div class='big-number'>"+c.patients+"</div></div><div class='info-card'><h3>Observations</h3><div class='big-number'>"+c.signals+"</div></div><div class='info-card'><h3>Conditions</h3><div class='big-number'>"+c.conditions+"</div></div></div><div class='panel'><p class='eyebrow'>PROVENANCE</p><h2>"+esc(S.selectedSource?.endpoint||"Live source")+"</h2><p class='panel-copy'>Fetched "+esc(S.selectedSource?.freshness||"from the active source")+". Patient display names are redacted in the CARE & CTRL interface.</p></div>")}return await reportsDb()}
async function reportsDb(){return await api("/reports/summary").then(function(d){var r=d.events||[];return section("Reports","Trace what the system saw, recommended and what people decided.")+"<div class='cards'><div class='info-card'><h3>Audit events</h3><div class='big-number'>"+r.length+"</div></div><div class='info-card'><h3>Actions</h3><div class='big-number'>"+(d.actions||[]).reduce(function(a,x){return a+Number(x.count||0)},0)+"</div></div><div class='info-card'><h3>Sources</h3><div class='big-number'>"+(d.sources||[]).length+"</div></div></div>"})}
importCsv=async function(){var v=function(k){return $("#m_"+k).value||""},m={external_ref:v("ref"),display_name:v("name"),date_of_birth:v("dob"),sex:v("sex"),signal_type:v("type"),value_numeric:v("value"),unit:v("unit"),observed_at:v("obs")};if(!m.external_ref||!m.display_name){toast("Mapping required","Select patient reference and display name.");return}var rows=S.rows.map(function(r){return Object.fromEntries(S.headers.map(function(h,i){return [h,r[i]??""]}))});try{var d=await api("/data/import",{method:"POST",body:JSON.stringify({rows:rows,mapping:m,file_name:S.file.name})});S.externalMode=false;S.selectedSource={id:d.source?.id||"csv-"+Date.now(),name:S.file.name,type:"IMPORTED SNAPSHOT",freshness:"Imported "+new Date().toLocaleTimeString("en-IN"),description:"Authorised healthcare CSV imported into the CARE & CTRL workspace.",source_status:"IMPORTED"};S.patients=[];$("#csvStatus").innerHTML="<div class='helper'><b>Import complete:</b> "+d.patients_imported+" patients · "+d.signals_imported+" signals. <b>IMPORTED SNAPSHOT</b> is now the active workspace source.</div>";toast("Workspace source switched","CARE & CTRL now reads the imported dataset.");await render()}catch(e){toast("Import failed",e.message)}}
useLiveEndpoint=async function(endpoint){try{var d=await api('/explorer/fhir-live?endpoint='+encodeURIComponent(endpoint));S.selectedSource={...S.selectedSource,id:'live-fhir-'+Date.now(),type:'LIVE FHIR',freshness:'Live · fetched '+new Date(d.fetched_at).toLocaleTimeString('en-IN'),endpoint:d.source,description:'Current response from the selected public FHIR endpoint.',resource_counts:d.resource_counts,unavailable_resources:d.unavailable_resources};S.patients=d.patients||[];S.externalMode=true;S.view='patients';toast('LIVE FHIR connected',d.count+' patient records · '+d.resource_counts.Observation+' observations returned.');await render()}catch(e){toast('Live FHIR connection failed',e.message)}}
refreshExternalSource=async function(){if(!S.externalMode)return;var isLive=S.selectedSource?.type==="LIVE FHIR",isHapi=S.selectedSource?.id==="hapi-r4";if(!isLive&&!isHapi)return;try{var d=isLive?await api('/explorer/fhir-live?endpoint='+encodeURIComponent(S.selectedSource.endpoint)):await api('/explorer/fhir-patients?count=50');S.patients=d.patients||[];S.selectedSource.freshness=(isLive?'LIVE · ':'TEST · ')+new Date(d.fetched_at||Date.now()).toLocaleTimeString('en-IN');if(d.resource_counts)S.selectedSource.resource_counts=d.resource_counts;if(S.view==="patients"||S.view==="population")await render();$("#dataState").textContent="SOURCE LIVE · "+new Date(d.fetched_at||Date.now()).toLocaleTimeString("en-IN")}catch(e){S.selectedSource.stale=true;$("#dataState").textContent="SOURCE STALE · "+(S.selectedSource?.type||"DATA")}}

async function render(){document.querySelectorAll(".nav-item").forEach(function(b){b.classList.toggle("active",b.dataset.view===S.view)});$("#viewTitle").textContent=titles[S.view];try{$("#app").innerHTML=S.view==="home"?home():S.view==="patients"?await patients():S.view==="population"?population():S.view==="network"?await network():S.view==="resources"?await resources():S.view==="actions"?await actions():S.view==="reports"?await reports():S.view==="explorer"?await explorer():dataView();bind()}catch(e){$("#app").innerHTML="<div class='empty'><div class='empty-icon'>!</div><h2>Could not load this workspace</h2><p>"+esc(e.message)+"</p><button class='button primary' data-retry>Retry</button></div>";bind()}}
async function findHospitals(q){q=String(q||"").trim();if(!q){toast("Choose a location","Enter a city, state or country.");return}$("#hospitalResults").innerHTML="<div class='loading-card'>Searching verified facility data…</div>";try{var d=await api("/explorer/hospitals?q="+encodeURIComponent(q));S.hospitals=d.hospitals||[];$("#hospitalResults").innerHTML=hospitalRows(S.hospitals,d);bind()}catch(e){$("#hospitalResults").innerHTML="<div class='empty'><div class='empty-icon'>!</div><h2>Hospital search unavailable</h2><p>"+esc(e.message)+"</p></div>"}} 
async function nearMe(){if(!navigator.geolocation){toast("Location unavailable","Enter your city instead.");return}$("#nearMe").disabled=true;navigator.geolocation.getCurrentPosition(async function(pos){try{var d=await api("/explorer/hospitals?lat="+pos.coords.latitude+"&lon="+pos.coords.longitude+"&radius=25000");S.hospitals=d.hospitals||[];$("#hospitalResults").innerHTML=hospitalRows(S.hospitals,d);bind()}catch(e){toast("Nearby search failed",e.message)}finally{$("#nearMe").disabled=false}},function(){toast("Location permission needed","Allow location access or search your city.");$("#nearMe").disabled=false},{enableHighAccuracy:true,timeout:10000,maximumAge:300000})}
function hospitalRows(rows,d){if(!rows.length)return "<div class='empty'><div class='empty-icon'>⌖</div><h2>No hospitals found</h2><p>Try a broader city/state/country search.</p></div>";return "<div class='results-head'><span>"+rows.length+" facilities found</span><small>"+esc(d.freshness||"Directory data")+" · "+esc(d.source||"Verified source")+"</small></div>"+rows.map(function(h){return "<article class='hospital-row'><div class='hospital-main'><div class='hospital-icon'>+</div><div><h3>"+esc(h.name)+"</h3><p>"+esc([h.city,h.state,h.country].filter(Boolean).join(" · ")||"Location available")+"</p><small>"+esc(h.patientData)+"</small></div></div><div class='hospital-actions'>"+(h.website?"<a class='button' target='_blank' rel='noopener' href='"+esc(h.website)+"'>Website ↗</a>":"")+"<button class='button primary' data-facility='"+esc(h.id)+"'>Use facility</button></div></article>"}).join("")}
async function useFacility(h){S.selectedSource={id:"facility-"+h.id,name:h.name,region:[h.city,h.state,h.country].filter(Boolean).join(", "),type:"FACILITY CONTEXT",freshness:"Community-updated",description:"Facility and location context from OpenStreetMap. This directory does not provide private patient records.",url:"https://www.openstreetmap.org/",facility:h};S.externalMode=true;S.view="explorer";await render();setTimeout(function(){var el=document.querySelector("#facilityConnection");if(el)el.scrollIntoView({behavior:"smooth",block:"center"})},80)}
async function bindFacilityButtons(){document.querySelectorAll("[data-facility]").forEach(function(b){b.onclick=function(){var h=S.hospitals.find(function(x){return String(x.id)===String(b.dataset.facility)});if(h)useFacility(h)}})}
async function edgeCopilot(){var base=(localStorage.getItem("care_ctrl_snapdragon_endpoint")||"http://127.0.0.1:18181/v1").replace(/\/$/,"");var q="Summarise the connected CARE & CTRL context for a healthcare operations user. Do not diagnose. If evidence is missing, say so.";var ctx=JSON.stringify({source:S.selectedSource,patients:S.patients.slice(0,40),generated_at:new Date().toISOString()});$("#copilotAnswer").innerHTML="<div class='ai-answer'><h3>Connecting to Snapdragon Edge…</h3><p>Trying the configured GenieX OpenAI-compatible local endpoint.</p></div>";try{var mr=await fetch(base+"/models");if(!mr.ok)throw Error("Snapdragon Edge endpoint is not reachable");var models=await mr.json(),model=models.data?.[0]?.id;if(!model)throw Error("No GenieX model is available");var rr=await fetch(base+"/chat/completions",{method:"POST",headers:{"Content-Type":"application/json","Authorization":"Bearer geniex"},body:JSON.stringify({model:model,messages:[{role:"system",content:"You are the CARE & CTRL local edge copilot. Use only supplied context. Never invent clinical facts. Do not diagnose."},{role:"user",content:q+"\nContext:\n"+ctx}],temperature:.2,max_tokens:300})});if(!rr.ok)throw Error("Snapdragon inference request failed");var out=await rr.json();var ans=out.choices?.[0]?.message?.content||"No edge response.";$("#copilotAnswer").innerHTML="<div class='ai-answer'><h3>Snapdragon Edge Copilot</h3><p>"+esc(ans)+"</p><small>Local GenieX endpoint · model "+esc(model)+" · patient context stayed on the connected path.</small></div>"}catch(e){$("#copilotAnswer").innerHTML="<div class='ai-answer'><h3>Snapdragon Edge is not connected</h3><p>"+esc(e.message)+". CARE & CTRL is ready for a GenieX OpenAI-compatible endpoint; no fake edge result is shown.</p><small>Default endpoint: "+esc(base)+"</small></div>"}} 
async function useLiveEndpoint(endpoint){try{var d=await api('/explorer/fhir-live?endpoint='+encodeURIComponent(endpoint));S.selectedSource={...S.selectedSource,id:'live-fhir-'+Date.now(),type:'LIVE FHIR',accessState:'CONNECTED',freshness:'Fetched '+new Date(d.fetched_at).toLocaleTimeString('en-IN'),endpoint:d.source,description:'Current response from the selected facility FHIR endpoint.',resource_counts:d.resource_counts||{},unavailable_resources:d.unavailable_resources||[],data_status:d.data_status||'LIVE FHIR'};S.patients=d.patients||[];S.externalMode=true;S.view='home';toast('Live FHIR data connected',d.count+' patient records loaded from the selected endpoint.');await render()}catch(e){S.selectedSource={...(S.selectedSource||{}),accessState:'AUTHORIZATION REQUIRED',error:e.message};S.externalMode=true;S.view='explorer';toast('Patient access requires authorization',e.message);await render()}}
function bind(){bindFacilityButtons();document.querySelectorAll("[data-scroll-hospitals]").forEach(function(b){b.onclick=function(){document.querySelector("#locationQuery")?.scrollIntoView({behavior:"smooth",block:"center"});document.querySelector("#locationQuery")?.focus()}});document.querySelectorAll("[data-live-endpoint]").forEach(function(b){b.onclick=function(){useLiveEndpoint(b.dataset.liveEndpoint)}});$("#manualFhirBtn")?.addEventListener("click",function(){var v=$("#manualFhirEndpoint")?.value.trim();if(!v){toast("FHIR endpoint required","Paste the authorised R4 base URL first.");return}useLiveEndpoint(v)});document.querySelectorAll('[data-connect-source]').forEach(function(b){b.onclick=function(){useDataSource(S.sources.find(function(s){return s.id===b.dataset.connectSource}))}});document.querySelectorAll('[data-scroll-csv]').forEach(function(b){b.onclick=function(){var f=document.querySelector('#csvFile');if(f){f.scrollIntoView({behavior:'smooth',block:'center'});setTimeout(function(){f.click()},180)}}});$("#edgeCopilot")?.addEventListener("click",edgeCopilot);document.querySelectorAll("[data-view]").forEach(function(b){b.onclick=function(){S.view=b.dataset.view;render()}});$("#findHospitals")?.addEventListener("click",function(){findHospitals($("#locationQuery").value)});$("#locationQuery")?.addEventListener("keydown",function(e){if(e.key==="Enter")findHospitals(e.target.value)});$("#nearMe")?.addEventListener("click",nearMe);$("#addPatient")?.addEventListener("click",patientModal);$("#patientSearch")?.addEventListener("input",function(e){$("#patientList").innerHTML=patientRows(S.patients.filter(function(p){return (p.display_name+" "+p.external_ref).toLowerCase().includes(e.target.value.toLowerCase())}))});document.querySelectorAll("[data-patient]").forEach(function(b){b.onclick=async function(){S.selected=b.dataset.patient;$("#patientDetail").innerHTML=await patientDetail(S.selected);bind()}});document.querySelectorAll("[data-signal]").forEach(function(b){b.onclick=function(){signalModal(b.dataset.signal)}});document.querySelectorAll("[data-action]").forEach(function(b){b.onclick=function(){changeAction(b.dataset.action,b.dataset.status)}});$("#simulatorBtn")?.addEventListener("click",simulator);$("#csvFile")?.addEventListener("change",handleCsv);$("#sourceSearch")?.addEventListener("input",async function(e){var d=await api("/explorer/sources?q="+encodeURIComponent(e.target.value));$("#sourceList").innerHTML=sourceRows(d.sources||[]);bind()});document.querySelectorAll("[data-source]").forEach(function(b){b.onclick=function(){sourceInfo(S.sources.find(function(s){return s.id===b.dataset.source}))}});document.querySelectorAll(".prompt").forEach(function(b){b.onclick=function(){copilot(b.dataset.p)}});$("[data-retry]")?.addEventListener("click",render)}
function form(title,desc,fields,done){$("#modalRoot").innerHTML="<div class='modal-backdrop' id='modal'><div class='modal'><p class='eyebrow'>WORKSPACE INPUT</p><h2>"+title+"</h2><p>"+desc+"</p><form id='mf'><div class='form-grid'>"+fields.map(function(f){return "<div class='field'><label>"+f.l+"</label><input name='"+f.n+"' type='"+(f.type||"text")+"' placeholder='"+esc(f.p||"")+"'></div>"}).join("")+"</div><div class='modal-actions'><button type='button' class='button' id='closeModal'>Cancel</button><button class='button primary'>Save</button></div></form></div></div>";$("#closeModal").onclick=function(){$("#modal").remove()};$("#mf").onsubmit=async function(e){e.preventDefault();try{await done(Object.fromEntries(new FormData(e.target).entries()))}catch(x){toast("Could not save",x.message)}}}
function patientModal(){form("Register patient","Create a patient Digital Twin record in your authorised workspace.",[{n:"external_ref",l:"PATIENT REFERENCE",p:"PT-001"},{n:"display_name",l:"DISPLAY NAME",p:"Patient name"},{n:"date_of_birth",l:"DATE OF BIRTH",type:"date"},{n:"sex",l:"SEX",p:"Female / Male / Other"}],async function(v){await api("/patients/create",{method:"POST",body:JSON.stringify(v)});$("#modal").remove();toast("Patient registered","Digital Twin created.");render()})}
function signalModal(id){form("Add patient signal","Record a verified timestamped measurement. This does not invent a wearable feed.",[{n:"signal_type",l:"SIGNAL TYPE",p:"heart_rate"},{n:"value_numeric",l:"VALUE",p:"72",type:"number"},{n:"unit",l:"UNIT",p:"bpm"},{n:"observed_at",l:"OBSERVED AT",type:"datetime-local"}],async function(v){if(v.observed_at)v.observed_at=new Date(v.observed_at).toISOString();await api("/signals/ingest",{method:"POST",body:JSON.stringify(Object.assign(v,{patient_id:id}))});$("#modal").remove();toast("Signal recorded","Patient timeline updated.");render()})}
function simulator(){$("#modalRoot").innerHTML="<div class='modal-backdrop' id='modal'><div class='modal'><p class='eyebrow'>WHAT-IF SIMULATOR</p><h2>Change an assumption. See the consequence.</h2><p>This is decision support, not an automatic clinical decision.</p><div class='field'><label>EXPECTED DAILY DEMAND CHANGE</label><input id='sim' type='range' min='-30' max='50' value='10'><div class='sim-label'><span>-30%</span><b id='sv'>+10%</b><span>+50%</span></div></div><div class='info-card'><h3>Projected pressure</h3><div class='big-number' id='sp'>Moderate</div><p id='st'>A modest increase may shorten operational headroom.</p></div><div class='modal-actions'><button class='button' id='closeModal'>Close</button></div></div></div>";$("#closeModal").onclick=function(){$("#modal").remove()};$("#sim").oninput=function(e){var v=+e.target.value;$("#sv").textContent=(v>=0?"+":"")+v+"%";$("#sp").textContent=v>25?"High":v>8?"Moderate":"Low";$("#st").textContent=v>25?"Review capacity and redistribution options.":v>8?"A modest increase may shorten operational headroom.":"No additional pressure under this assumption."}}
async function useDataSource(s){if(!s)return;S.selectedSource=s;try{if(s.id==="hapi-r4"){var d=await api("/explorer/fhir-patients?count=50");S.patients=d.patients||[];S.externalMode=true;S.view="patients";$("#modal")?.remove();toast("Patient data connected",S.patients.length+" synthetic/test patients loaded from HAPI FHIR.");await render()}else if(s.type==="LIVE"){toast("Authorisation required","Connect your organisation's authorised FHIR endpoint before patient records can be loaded.")}else{toast("Source selected",s.name+" is available as "+s.type.toLowerCase()+" context; it does not expose a live patient feed.")}}catch(e){toast("Source connection failed",e.message)}}
function sourceInfo(s){if(!s)return;$("#modalRoot").innerHTML="<div class='modal-backdrop' id='modal'><div class='modal'><p class='eyebrow'>"+esc(s.type)+" · "+esc(s.region)+"</p><h2>"+esc(s.name)+"</h2><p>"+esc(s.description)+"</p><div class='data-card'><div class='data-line'><span>Freshness</span><b>"+esc(s.freshness)+"</b></div><div class='data-line'><span>Patient-data capability</span><b>"+(s.patientFeed?"Available from this source":"Not provided by this source")+"</b></div></div><div class='modal-actions'><a class='button' target='_blank' rel='noopener' href='"+esc(s.url)+"'>Open source ↗</a><button class='button primary' id='useDataSource'>Use this data source</button><button class='button' id='closeModal'>Close</button></div></div></div>";$("#closeModal").onclick=function(){$("#modal").remove()};$("#useDataSource").onclick=function(){useDataSource(s)}}
function parseCsv(t){var out=[],row=[],cell="",q=false;for(var i=0;i<t.length;i++){var c=t[i],n=t[i+1];if(c==='"'&&q&&n==='"'){cell+='"';i++;continue}if(c==='"'){q=!q;continue}if(c===","&&!q){row.push(cell);cell="";continue}if((c==="\n"||c==="\r")&&!q){if(c==="\r"&&n==="\n")i++;row.push(cell);if(row.some(function(x){return x.trim()}))out.push(row);row=[];cell="";continue}cell+=c}if(cell||row.length){row.push(cell);out.push(row)}return out}
function handleCsv(e){var f=e.target.files?.[0];if(!f)return;var r=new FileReader();r.onload=function(){var p=parseCsv(String(r.result||""));S.file=f;S.headers=p[0]||[];S.rows=p.slice(1).filter(function(x){return x.some(function(y){return y.trim()})});mapCsv()};r.readAsText(f)}
function mapCsv(){
  var fields=[
    ["ref","PATIENT REFERENCE","Required","id,patient_id,patient id,identifier,reference,patient reference,external_ref,external ref"],
    ["name","DISPLAY NAME","Required","name,patient name,display name,patient,patient_name,humanname"],
    ["dob","DATE OF BIRTH","Optional","dob,date of birth,birthdate,birth date,date_of_birth"],
    ["sex","SEX","Optional","sex,gender"],
    ["type","SIGNAL TYPE","Optional","signal type,signal_type,observation,observation type,measurement,type,code"],
    ["value","SIGNAL VALUE","Optional","signal value,signal_value,value,value numeric,value_numeric,measurement value"],
    ["unit","SIGNAL UNIT","Optional","signal unit,signal_unit,unit,units"],
    ["obs","OBSERVED AT","Optional","observed at,observed_at,timestamp,time,date,datetime,date time,effective"]
  ];
  function norm(x){return String(x||"").toLowerCase().replace(/[{}()[\]_-]+/g," ").replace(/\s+/g," ").trim()}
  function guess(aliases){
    var a=aliases.split(",").map(norm);
    var exact=S.headers.find(function(h){return a.indexOf(norm(h))>=0}); if(exact)return exact;
    return S.headers.find(function(h){var n=norm(h);return a.some(function(x){return x.length>3&&(n.includes(x)||x.includes(n))})})||"";
  }
  function options(selected){
    var groups={identity:[],clinical:[],other:[]};
    S.headers.forEach(function(h){
      var n=norm(h),g=/id|identifier|patient|name|birth|dob|sex|gender/.test(n)?"identity":/signal|observ|value|unit|heart|glucose|pressure|condition|diagnos|date|time|code/.test(n)?"clinical":"other";
      groups[g].push(h);
    });
    return "<option value=''>— not mapped —</option>"+
      "<optgroup label='Identity'>"+groups.identity.map(function(h){return "<option value='"+esc(h)+"' "+(h===selected?"selected":"")+">"+esc(h)+"</option>"}).join("")+"</optgroup>"+
      "<optgroup label='Clinical / signals'>"+groups.clinical.map(function(h){return "<option value='"+esc(h)+"' "+(h===selected?"selected":"")+">"+esc(h)+"</option>"}).join("")+"</optgroup>"+
      "<optgroup label='Other columns'>"+groups.other.map(function(h){return "<option value='"+esc(h)+"' "+(h===selected?"selected":"")+">"+esc(h)+"</option>"}).join("")+"</optgroup>";
  }
  var mapped=fields.map(function(x){return [x[0],x[1],x[2],guess(x[3])]});
  var identity=mapped.slice(0,4),signals=mapped.slice(4);
  function fieldHtml(x){
    var required=x[2]==="Required";
    return "<div class='csv-field "+(required?"required":"")+"'><div class='csv-field-head'><label for='m_"+x[0]+"'>"+esc(x[1])+"</label><span>"+(required?"REQUIRED":"OPTIONAL")+"</span></div><select id='m_"+x[0]+"' aria-label='"+esc(x[1])+"'>"+options(x[3])+"</select></div>";
  }
  var preview=S.rows.slice(0,4).map(function(r){return "<tr>"+S.headers.slice(0,Math.min(5,S.headers.length)).map(function(_,i){return "<td>"+esc(r[i]??"")+"</td>"}).join("")+"</tr>"}).join("");
  var heads=S.headers.slice(0,Math.min(5,S.headers.length)).map(function(h){return "<th>"+esc(h)+"</th>"}).join("");
  $("#csvStatus").innerHTML="<div class='csv-wizard'>"+
    "<div class='csv-wizard-head'><div><p class='eyebrow'>CSV IMPORT WIZARD</p><h2>Map your healthcare data</h2><p>We detected <b>"+S.rows.length+"</b> rows and <b>"+S.headers.length+"</b> columns. CARE & CTRL has suggested mappings below. Review them before import.</p></div><span class='source-badge sim'>IMPORTED SNAPSHOT</span></div>"+
    "<div class='csv-steps'><span class='done'>1 File loaded</span><span class='active'>2 Map columns</span><span>3 Validate</span><span>4 Import</span></div>"+
    "<div class='csv-section'><div class='csv-section-title'><div><b>Patient identity</b><small>How CARE & CTRL identifies each patient</small></div><span>4 fields</span></div><div class='mapping'>"+identity.map(fieldHtml).join("")+"</div></div>"+
    "<div class='csv-section'><div class='csv-section-title'><div><b>Clinical signals</b><small>Optional measurements and timestamps attached to the patient</small></div><span>4 fields</span></div><div class='mapping'>"+signals.map(fieldHtml).join("")+"</div></div>"+
    "<div class='csv-section csv-preview'><div class='csv-section-title'><div><b>Data preview</b><small>First 4 rows · first 5 columns</small></div><span>"+S.rows.length+" total rows</span></div><div class='preview'><table><thead><tr>"+heads+"</tr></thead><tbody>"+preview+"</tbody></table></div></div>"+
    "<div class='csv-actions'><div><b>Ready to validate?</b><small>Required: Patient Reference + Display Name</small></div><button class='button primary' id='importBtn'>Validate & import →</button></div>"+
    "</div>";
  $("#importBtn").onclick=importCsv;
}
async function importCsv(){var v=function(k){return $("#m_"+k).value||""},m={external_ref:v("ref"),display_name:v("name"),date_of_birth:v("dob"),sex:v("sex"),signal_type:v("type"),value_numeric:v("value"),unit:v("unit"),observed_at:v("obs")};if(!m.external_ref||!m.display_name){toast("Mapping required","Select patient reference and display name.");return}var rows=S.rows.map(function(r){return Object.fromEntries(S.headers.map(function(h,i){return [h,r[i]??""]}))});try{var d=await api("/data/import",{method:"POST",body:JSON.stringify({rows:rows,mapping:m,file_name:S.file.name})});$("#csvStatus").innerHTML="<div class='helper'><b>Import complete:</b> "+d.patients_imported+" patients · "+d.signals_imported+" signals. Source is an <b>IMPORTED SNAPSHOT</b>, not LIVE.</div>";toast("Import complete","Workspace data updated.");loadOverview()}catch(e){toast("Import failed",e.message)}}
async function changeAction(id,status){try{await api("/actions/"+id,{method:"POST",body:JSON.stringify({status:status})});toast(status==="approved"?"Action approved":"Action rejected","Decision written to audit trail.");render()}catch(e){toast("Decision failed",e.message)}}
async function copilot(k){try{var d;if(S.externalMode){d={pending_actions:0,patients_needing_attention:S.patients.filter(function(p){return p.status==="active"}).length,facilities:S.selectedSource?1:0,resource_records:0,latest_action_status:"No action generated yet from this source"}}else d=await api("/copilot/context");var q=k==="attention"?"What needs attention in this connected healthcare dataset?":k==="pressure"?"Where is operational pressure building, based only on the connected data?":"Explain the latest action or decision state from the connected data.";var ctx={source:S.selectedSource||null,patients:S.patients.slice(0,80),workspace:d,generated_at:new Date().toISOString()};$("#copilotAnswer").innerHTML="<div class='ai-answer'><h3>Analysing verified context…</h3><p>Gemini is reading the connected source and will not invent missing values.</p></div>";var out=await api("/copilot/ask",{method:"POST",body:JSON.stringify({question:q,context:ctx})});$("#copilotAnswer").innerHTML="<div class='ai-answer'><h3>Grounded AI analysis</h3><p>"+esc(out.answer)+"</p><small>Gemini · CARE & CTRL source context · "+new Date().toLocaleTimeString("en-IN")+"</small></div>"}catch(e){$("#copilotAnswer").innerHTML="<div class='ai-answer'><h3>AI is temporarily unavailable</h3><p>"+esc(e.message)+"</p></div>"}}
async function loadOverview(){try{S.overview=await api("/system/overview");$("#dataState").textContent=S.overview.connected_sources?"DATA CONNECTED":"DATA AWAITING";$("#dataDot").style.background=S.overview.connected_sources?"#27b4a7":"#b97817";$("#systemStatus").textContent=S.overview.connected_sources?"System operational":"Ready for verified sources";$("#systemSub").textContent=S.overview.connected_sources?"Backend connected · verified sources available":"Backend connected · awaiting verified sources";$("#systemDot").style.background=S.overview.connected_sources?"#43c2a8":"#b97817"}catch(e){$("#dataState").textContent="CONNECTION ISSUE";$("#systemDot").style.background="#b33b45";$("#systemStatus").textContent="API unavailable"}}
async function workspace(){var d=await api("/hospital/context");S.member=d.member;if(!S.member){S.externalMode=true;$("#modalRoot").innerHTML="<div class='modal-backdrop' id='modal'><div class='modal'><p class='eyebrow'>WELCOME TO CARE & CTRL</p><h2>Choose how you want to start</h2><p>First, connect a healthcare data source. You can create an organisation workspace now, or explore hospitals and public/research sources without creating one yet.</p><form id='setup'><div class='form-grid'><div class='field'><label>ORGANISATION / HOSPITAL</label><input name='name' required placeholder='City Care Hospital'></div><div class='field'><label>CITY</label><input name='city' placeholder='Chennai'></div><div class='field'><label>STATE</label><input name='state' placeholder='Tamil Nadu'></div></div><div class='modal-actions'><button type='button' class='button' id='skipWorkspace'>Continue without workspace</button><button class='button primary'>Create workspace</button></div></form></div></div>";$("#skipWorkspace").onclick=function(){$("#modal").remove();S.view="explorer";render()};$("#setup").onsubmit=async function(e){e.preventDefault();try{await api("/hospital/onboard",{method:"POST",body:JSON.stringify(Object.fromEntries(new FormData(e.target).entries()))});S.externalMode=false;$("#modal").remove();await boot()}catch(x){toast("Setup failed",x.message)}}}}
async function refreshExternalSource(){if(!S.externalMode||!S.selectedSource)return;try{var d;if(S.selectedSource.type==="LIVE FHIR"&&S.selectedSource.endpoint){d=await api("/explorer/fhir-live?endpoint="+encodeURIComponent(S.selectedSource.endpoint))}else if(S.selectedSource.id==="hapi-r4"){d=await api("/explorer/fhir-patients?count=50")}else{return}S.patients=d.patients||[];S.selectedSource.freshness="Fetched "+new Date(d.fetched_at||Date.now()).toLocaleTimeString("en-IN");if(d.resource_counts)S.selectedSource.resource_counts=d.resource_counts;if(d.unavailable_resources)S.selectedSource.unavailable_resources=d.unavailable_resources;S.selectedSource.accessState="CONNECTED";if(S.view==="patients"||S.view==="home"||S.view==="data")await render();$("#dataState").textContent="SOURCE SYNCED · "+new Date().toLocaleTimeString("en-IN")}catch(e){S.selectedSource.accessState="STALE / ACCESS ERROR";$("#dataState").textContent="SOURCE STALE"}} 
async function boot(){await workspace();await loadOverview();await render();setInterval(function(){if(document.visibilityState==="visible"){loadOverview();refreshExternalSource()}},90000)}
$("#menuBtn").onclick=function(){$("#sidebar").classList.toggle("open")};$("#refreshBtn").onclick=function(){loadOverview();render();toast("Refreshing","Checking the latest workspace state.")};$("#signoutBtn").onclick=async function(){try{await window.hatchable.auth?.signOut()}finally{location.replace("/login")}};
(async function(){if(!window.hatchable?.auth){location.replace("/login");return}try{var s=await window.hatchable.auth.getSession();if(!s?.user){location.replace("/login?next="+encodeURIComponent(location.pathname));return}$("#avatar").textContent=(s.user.name||s.user.email||"CC").split(/\s+/).map(function(x){return x[0]}).slice(0,2).join("").toUpperCase();await boot()}catch(e){toast("Session issue",e.message);setTimeout(function(){location.replace("/login")},500)}})();